1	import { NextResponse } from "next/server";
2	import { getHealth, type CompStatus, type HealthReport } from "@/lib/monitoring";
3	
4	export const dynamic = "force-dynamic";
5	export const runtime = "nodejs";
6	
7	/**
8	 * GET /api/health — public, unauthenticated health probe.
9	 *
10	 * Returns { web, db, worker, proxmox } where each is
11	 * { status: "operational" | "degraded" | "down", detail }.
12	 *
13	 * IMPORTANT: `getHealth()` embeds raw upstream error text in component details
14	 * (e.g. DB connection strings / auth-failure messages, internal host:port).
15	 * Because this endpoint is unauthenticated we NEVER pass those through — each
16	 * component is mapped to a coarse public status and a generic, secret-free
17	 * detail string before responding.
18	 *
19	 * Cached ~15s in-process so external monitors / the status page don't hammer
20	 * the DB and Proxmox on every request.
21	 */
22	
23	const TTL_MS = 15_000;
24	let cache: { at: number; body: HealthReport } | null = null;
25	
26	/** Fixed, secret-free copy per component + status. Never derived from upstream text. */
27	const PUBLIC_DETAIL: Record<CompStatus, string> = {
28	  operational: "operational",
29	  degraded: "degraded",
30	  down: "unavailable",
31	};
32	
33	type PublicComponent = { status: CompStatus; detail: string };
34	type PublicHealth = {
35	  web: PublicComponent;
36	  db: PublicComponent;
37	  worker: PublicComponent;
38	  proxmox: PublicComponent;
39	  checkedAt: string;
40	};
41	
42	function sanitize(report: HealthReport): PublicHealth {
43	  const pub = (status: CompStatus): PublicComponent => ({ status, detail: PUBLIC_DETAIL[status] });
44	  return {
45	    web: pub(report.web.status),
46	    db: pub(report.db.status),
47	    worker: pub(report.worker.status),
48	    proxmox: pub(report.proxmox.status),
49	    checkedAt: report.checkedAt,
50	  };
51	}
52	
53	export async function GET() {
54	  try {
55	    if (!cache || Date.now() - cache.at > TTL_MS) {
56	      cache = { at: Date.now(), body: await getHealth() };
57	    }
58	    const worstDown =
59	      cache.body.db.status === "down" || cache.body.proxmox.status === "down";
60	    return NextResponse.json(sanitize(cache.body), {
61	      status: worstDown ? 503 : 200,
62	      headers: { "Cache-Control": "public, max-age=15, s-maxage=15" },
63	    });
64	  } catch {
65	    // Never leak the underlying failure text to an unauthenticated caller.
66	    return NextResponse.json({ error: "health check failed" }, { status: 500 });
67	  }
68	}
