100	export type StorageUsage = {
101	  node: string;
102	  storage: string;
103	  total: number;
104	  used: number;
105	  avail: number;
106	  ratio: number;
107	  reachable: boolean;
108	};
109	
110	/** Per-node, per-storage disk usage (bytes). Unreachable storages are marked. */
111	export async function nodeStorageUsage(): Promise<StorageUsage[]> {
112	  const targets = await nodeTargets();
113	  const out: StorageUsage[] = [];
114	  for (const t of targets) {
115	    for (const storage of t.storages) {
116	      try {
117	        const st = await t.get(`/nodes/${t.pveNode}/storage/${storage}/status`);
118	        const total = Number(st?.total ?? 0);
119	        const used = Number(st?.used ?? 0);
120	        const avail = Number(st?.avail ?? Math.max(0, total - used));
121	        out.push({
122	          node: t.label,
123	          storage,
124	          total,
125	          used,
126	          avail,
127	          ratio: total > 0 ? used / total : 0,
128	          reachable: true,
129	        });
130	      } catch {
131	        out.push({ node: t.label, storage, total: 0, used: 0, avail: 0, ratio: 0, reachable: false });
132	      }
133	    }
134	  }
135	  return out;
136	}
137	
138	export type NodeRam = {
139	  node: string;
140	  total: number;
141	  used: number;
142	  ratio: number;
143	  cpu: number;
144	  reachable: boolean;
145	};
146	
147	/** Per-node RAM + CPU load from the node status endpoint. */
148	export async function nodeRamUsage(): Promise<NodeRam[]> {
149	  const targets = await nodeTargets();
150	  return Promise.all(
151	    targets.map(async (t) => {
152	      try {
153	        const s = await t.get(`/nodes/${t.pveNode}/status`);
154	        const total = Number(s?.memory?.total ?? 0);
155	        const used = Number(s?.memory?.used ?? 0);
156	        return {
157	          node: t.label,
158	          total,
159	          used,
160	          ratio: total > 0 ? used / total : 0,
161	          cpu: Number(s?.cpu ?? 0),
162	          reachable: true,
163	        };
164	      } catch {
165	        return { node: t.label, total: 0, used: 0, ratio: 0, cpu: 0, reachable: false };
166	      }
167	    })
168	  );
169	}
170	
171	export type BackupSummary = {
172	  count: number;
173	  /** Unix seconds of the most recent backup (freshness signal). */
174	  newestCtime: number | null;
175	  /** Unix seconds of the oldest backup on disk. */
176	  oldestCtime: number | null;
177	  reachable: boolean;
178	};
179	
180	/**
181	 * Summarise backups across all nodes' `backup` storage. Best-effort: if the
182	 * storage/content endpoint isn't available the node is simply skipped.
183	 */
184	export async function backupSummary(): Promise<BackupSummary> {
185	  const targets = await nodeTargets();
186	  let count = 0;
187	  let newest: number | null = null;
188	  let oldest: number | null = null;
189	  let reachable = false;
190	  for (const t of targets) {
191	    try {
192	      const items: any[] = await t.get(`/nodes/${t.pveNode}/storage/backup/content`, {
193	        content: "backup",
194	      });
195	      reachable = true;
196	      for (const b of items ?? []) {
197	        const ct = Number(b?.ctime ?? 0);
198	        if (!ct) continue;
199	        count++;
200	        if (newest === null || ct > newest) newest = ct;
201	        if (oldest === null || ct < oldest) oldest = ct;
202	      }
203	    } catch {
204	      // storage/content not available on this node — skip
205	    }
206	  }
207	  return { count, newestCtime: newest, oldestCtime: oldest, reachable };
208	}
209	
210	// ---- Worker / job health -------------------------------------------------
211	
212	export type StuckJob = {
213	  id: string;
214	  type: string;
215	  updatedAt: Date;
216	  attempts: number;
217	  serverId: string | null;
218	  hostname: string | null;
219	};
220	
221	/** Jobs stuck in RUNNING past the stuck threshold. */
222	export async function stuckJobs(): Promise<StuckJob[]> {
223	  const rows = await db.job.findMany({
224	    where: { status: "RUNNING", updatedAt: { lt: new Date(Date.now() - STUCK_JOB_MS) } },
225	    orderBy: { updatedAt: "asc" },
226	    take: 20,
227	    select: {
228	      id: true,
229	      type: true,
230	      updatedAt: true,
231	      attempts: true,
232	      serverId: true,
233	      server: { select: { hostname: true } },
234	    },
235	  });
236	  return rows.map((r) => ({
237	    id: r.id,
238	    type: r.type,
239	    updatedAt: r.updatedAt,
240	    attempts: r.attempts,
241	    serverId: r.serverId,
242	    hostname: r.server?.hostname ?? null,
243	  }));
244	}
245	
246	export type WorkerHealth = {
247	  status: CompStatus;
248	  detail: string;
249	  newestUpdatedAt: Date | null;
250	  stuckRunning: number;
251	  queuedBacklog: number;
252	  staleQueued: number;
253	};
254	
255	/**
256	 * Worker liveness inferred from the Job queue:
257	 *  - QUEUED work older than WORKER_STALE_MS that hasn't been picked up ⇒ down
258	 *    (the loop isn't draining the queue).
259	 *  - Jobs stuck RUNNING past STUCK_JOB_MS ⇒ degraded.
260	 *  - Otherwise operational (an empty/fresh queue is healthy, even if idle).
261	 */
262	export async function workerHealth(): Promise<WorkerHealth> {
263	  const now = Date.now();
264	  const [newest, stuckRunning, queuedBacklog, staleQueued] = await Promise.all([
265	    db.job.findFirst({ orderBy: { updatedAt: "desc" }, select: { updatedAt: true } }),
266	    db.job.count({ where: { status: "RUNNING", updatedAt: { lt: new Date(now - STUCK_JOB_MS) } } }),
267	    db.job.count({ where: { status: "QUEUED" } }),
268	    db.job.count({ where: { status: "QUEUED", createdAt: { lt: new Date(now - WORKER_STALE_MS) } } }),
269	  ]);
270	
271	  let status: CompStatus = "operational";
272	  let detail = newest
273	    ? `last job update ${fmtAge(now - newest.updatedAt.getTime())} ago`
274	    : "idle — no jobs processed yet";
275	
276	  if (staleQueued > 0) {
277	    status = "down";
278	    detail = `${staleQueued} job(s) queued but not picked up — worker may be stopped`;
279	  } else if (stuckRunning > 0) {
280	    status = "degraded";
281	    detail = `${stuckRunning} job(s) stuck running > ${Math.round(STUCK_JOB_MS / 60_000)}m`;
282	  }
283	
284	  return {
285	    status,
286	    detail,
287	    newestUpdatedAt: newest?.updatedAt ?? null,
288	    stuckRunning,
289	    queuedBacklog,
290	    staleQueued,
291	  };
292	}
293	
294	// ---- Component health (db / proxmox) ------------------------------------
295	
296	async function dbHealth(): Promise<Component> {
297	  try {
298	    await db.$queryRaw`SELECT 1`;
299	    return { status: "operational", detail: "responding" };
300	  } catch (e: any) {
301	    return { status: "down", detail: String(e?.message ?? e).slice(0, 120) };
302	  }
303	}
304	
305	async function proxmoxHealth(): Promise<Component> {
306	  const targets = await nodeTargets();
307	  let ok = 0;
308	  let fail = 0;
309	  for (const t of targets) {
310	    try {
311	      await t.get(`/nodes/${t.pveNode}/status`);
312	      ok++;
313	    } catch {
314	      fail++;
315	    }
316	  }
317	  if (ok === 0) return { status: "down", detail: "no Proxmox node reachable" };
318	  if (fail > 0) return { status: "degraded", detail: `${fail} of ${ok + fail} nodes unreachable` };
319	  return { status: "operational", detail: `${ok} node(s) reachable` };
320	}
321	
322	/** Full health report — the source of truth for /api/health and /status. */
323	export async function getHealth(): Promise<HealthReport> {
324	  const [dbc, wh, px] = await Promise.all([dbHealth(), workerHealth(), proxmoxHealth()]);
325	  return {
326	    web: { status: "operational", detail: "serving requests" },
327	    db: dbc,
328	    worker: { status: wh.status, detail: wh.detail },
329	    proxmox: px,
330	    checkedAt: new Date().toISOString(),
331	  };
332	}
333	
334	/** Roll the four components up into a single worst-of status. */
335	export function overallStatus(h: HealthReport): CompStatus {
336	  const all = [h.web, h.db, h.worker, h.proxmox].map((c) => c.status);
337	  if (all.includes("down")) return "down";
338	  if (all.includes("degraded")) return "degraded";
339	  return "operational";
340	}
