127	/* ---------------- Activity feed ---------------- */
128	
129	type Activity = {
130	  id: string;
131	  at: Date;
132	  kind: "audit" | "payment" | "job";
133	  tone: "brand" | "green" | "amber" | "slate" | "red";
134	  label: string;
135	  text: string;
136	  actor?: string | null;
137	};
138	
139	async function ActivityTab() {
140	  const [audits, txns, jobs] = await Promise.all([
141	    db.auditLog.findMany({
142	      include: { user: { select: { email: true } } },
143	      orderBy: { createdAt: "desc" },
144	      take: 40,
145	    }),
146	    db.walletTransaction.findMany({
147	      include: { user: { select: { email: true } } },
148	      orderBy: { createdAt: "desc" },
149	      take: 40,
150	    }),
151	    db.job.findMany({ orderBy: { createdAt: "desc" }, take: 40 }),
152	  ]);
153	
154	  const items: Activity[] = [];
155	  const actors = await actorEmails(audits);
156	
157	  for (const a of audits) {
158	    // Same attribution rule as the Audit tab: an action taken while impersonating
159	    // belongs to the admin who took it, not to the account it was taken as.
160	    const asAdmin = actingAdminId(a.detail);
161	    items.push({
162	      id: `a-${a.id}`,
163	      at: a.createdAt,
164	      kind: "audit",
165	      tone: asAdmin || a.action.startsWith("admin.") ? "amber" : "brand",
166	      label: a.action,
167	      text: asAdmin ? detailWithoutActor(a.detail) : (a.detail ?? ""),
168	      actor: asAdmin
169	        ? `${actors.get(asAdmin) ?? asAdmin} — impersonating ${a.user?.email ?? "customer"}`
170	        : (a.user?.email ?? "system"),
171	    });
172	  }
173	  for (const t of txns) {
174	    const credit = t.amountCents >= 0;
175	    items.push({
176	      id: `t-${t.id}`,
177	      at: t.createdAt,
178	      kind: "payment",
179	      tone: credit ? "green" : "slate",
180	      label: credit ? "wallet.credit" : "wallet.debit",
181	      text: `${fmtMoney(t.amountCents)} · ${t.description}`,
182	      actor: t.user?.email ?? null,
183	    });
184	  }
185	  for (const j of jobs) {
186	    items.push({
187	      id: `j-${j.id}`,
188	      at: j.createdAt,
189	      kind: "job",
190	      tone: j.status === "FAILED" ? "red" : j.status === "DONE" ? "green" : "slate",
191	      label: `job.${String(j.type).toLowerCase()}`,
192	      text: `${j.status}${j.error ? ` · ${j.error}` : ""}`,
193	      actor: null,
194	    });
195	  }
196	
197	  items.sort((a, b) => b.at.getTime() - a.at.getTime());
