25	/** Loose sanity check for a literal IPv4/IPv6 address (no CIDR / ranges). */
26	function isPlainIp(s: string): boolean {
27	  return /^\d{1,3}(\.\d{1,3}){3}$/.test(s) || (s.includes(":") && /^[0-9a-fA-F:]+$/.test(s));
28	}
