195	      detail:
196	        `The last automatic backup attempt (${stamp(opts.lastAttempt.at)}) FAILED. ` +
197	        `${verifiedLine} Open a ticket if this repeats — do not assume tonight's run will fix it.`,
198	    };
199	  }
200	
201	  if (!verified) {
202	    if (!opts.lastAttempt) {
203	      return {
204	        state: "pending",
205	        detail: "No automatic backup has run yet — the first one is queued by the next sweep.",
206	      };
207	    }
208	    return {
209	      state: "never",
210	      detail:
211	        `Automatic backups have been attempted since ${stamp(opts.lastAttempt.at)}, but none has ` +
212	        "been verified to exist in storage. Do not rely on having a restore point.",
213	    };
214	  }
215	
216	  const overdueAfter = verified.getTime() + hours * 60 * 60_000 * STALE_INTERVAL_MULTIPLE;
217	  if (opts.now > overdueAfter) {
