export type ServerBackup = { volid: string; ctime?: number; size?: number };

/**
 * List the vzdump backups on the `backup` storage that belong to this server's
 * VMID. Read-only Proxmox call, ownership-checked.
 */
export async function listServerBackups(
  serverId: string
): Promise<{ error?: string; backups?: ServerBackup[] }> {
  const { server } = await ownedServer(serverId);
  if (!server.vmid) return { backups: [] };
  try {
    const backups = (await listBackups(server.vmid)) as ServerBackup[];
    backups.sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
    return { backups };
  } catch {
    return { error: "Could not reach the hypervisor — try again in a moment." };
  }
}

